import { Component, Input, Output, EventEmitter } from '@angular/core';
import { Router } from '@angular/router';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-software-package-card',
  templateUrl: './software-package-card.component.html',
  styleUrls: ['./software-package-card.component.css']
})
export class SoftwarePackageCardComponent {
  @Input() package!: SoftwarePackage;
  @Output() click = new EventEmitter<SoftwarePackage>();

  constructor(private router: Router) {}

  onClick(): void {
    this.click.emit(this.package);
  }

  orderPackage(event: Event): void {
    event.stopPropagation();
    this.router.navigate(['/packages', this.package.id, 'order']);
  }
}
<div class="card cursor-pointer" (click)="onClick()">
  <div class="h-32 mb-2 overflow-hidden rounded-xl bg-gray-100 border border-pink-lighter">
    <img
      [src]="package.thumbnail || package.images?.[0] || 'https://via.placeholder.com/200'"
      [alt]="package.title"
      class="w-full h-full object-cover hover:scale-105 transition-transform duration-500"
    />
  </div>

  <h3 class="font-bold text-gray-900 mb-1 line-clamp-2 text-gradient">{{ package.title }}</h3>

  <div class="flex items-center justify-between mb-2">
    <div class="flex items-center gap-3">
      <button (click)="orderPackage($event)" class="btn-primary text-xs font-bold px-3 py-1">
        Order Now
      </button>
    </div>
    <div class="flex items-center text-xs text-gray-600">
      <span class="badge badge-pink mr-1">⭐ {{ package.rating || 'N/A' }}</span>
    </div>
  </div>

  <p class="text-xs text-gray-600 line-clamp-2">{{ package.description }}</p>

  <div class="mt-3 flex items-center gap-2">
    <span class="font-bold text-pink-dark text-sm">${{ package.price }}</span>
    <span *ngIf="package.discountPercentage && package.discountPercentage > 0" class="badge badge-purple text-xs">
      -{{ package.discountPercentage }}%
    </span>
  </div>
</div>
